    if (bufs.head) {
      let node = bufs.head;
      while (node) { bufArr.push(node.data || node); node = node.next; }
    }
    let bytes = [];
    for (const b of bufArr) {
      if (b && b.data) bytes = bytes.concat(b.data);
      else if (b && b.type === 'Buffer' && b.data) bytes = bytes.concat(b.data);
    }
    if (bytes.length) {
      const str = String.fromCharCode(...bytes);
      try {
        const parsed = JSON.parse(str);
        if (parsed.output && Array.isArray(parsed.output)) {
          for (const block of parsed.output) {
            if (block.type === 'message' && Array.isArray(block.content)) {
              for (const c of block.content) {
                if (c.type === 'output_text') responseText += c.text || '';
                else if (c.text) responseText += c.text;
              }
            }
          }
        }
        if (!responseText && parsed.output) {
          responseText = JSON.stringify(parsed);
        }
      } catch(e2) { responseText = str; }
    }
  }
  // Case 3: string data
  else if (typeof resp.data === 'string') {
    try {
      const parsed = JSON.parse(resp.data);
      if (parsed.output && Array.isArray(parsed.output)) {
        for (const block of parsed.output) {
          if (block.type === 'message' && Array.isArray(block.content)) {
            for (const c of block.content) {
              if (c.type === 'output_text') responseText += c.text || '';
            }
          }
        }
      }
    } catch(e3) { responseText = resp.data; }
  }
  if (!responseText) responseText = '{}';
} catch(e) { responseText = '{}'; }

