      const bufArr = Array.isArray(bufs) ? bufs : [];
      if (bufs.head) { let node = bufs.head; while (node) { bufArr.push(node.data || node); node = node.next; } }
      let bytes = [];
      for (const b of bufArr) { if (b && b.data) bytes = bytes.concat(b.data); }
      if (bytes.length) {
        const str = String.fromCharCode(...bytes);
        const parsed = JSON.parse(str);
        if (parsed.output) {
